let healthSnapshot=null,healthChecked=false;
let releaseCapabilities=null,releaseCapabilitiesChecked=false;
const researchFeatureIds={hybrik:"hybrik_image_inference",gvhmr:"gvhmr_video_inference"};
function validReleaseCapabilities(value){return value?.schema==="kairyth-capabilities/v1"&&typeof value.profile_valid==="boolean"&&typeof value.release_profile==="string"&&Object.values(researchFeatureIds).every(id=>typeof value.features?.[id]?.enabled==="boolean"&&typeof value.features[id].state==="string")}
