function researchFeaturePresentation(backend){
  const feature=releaseCapabilities?.features?.[researchFeatureIds[backend]];
  if(!releaseCapabilitiesChecked||!healthChecked)return {state:"pending",badge:"正在检查",message:"正在读取发布能力…"};
  if(feature?.state==="disabled_experimental")return {state:"disabled_experimental",badge:"实验性 · 公开版暂不提供",message:"实验性，后续会更新与HybrIK以及GVHMR的兼容包"};
  if(!releaseCapabilities?.profile_valid||feature?.state!=="enabled")return {state:"disabled_configuration",badge:"配置未就绪",message:"发布配置未就绪，暂不启用新的图片或视频推理。已有资产功能不受影响。"};
  if(!healthSnapshot?.service_ready)return {state:"service_unavailable",badge:"服务未就绪",message:"工作台服务尚未就绪，暂不能新建推理任务。"};
  return {state:"enabled",badge:"研究 / 实验性",message:"本地研究模式：此入口按已配置的研究后端运行，资源与许可需分别满足。"};
}
function renderResearchAvailability(){
  const tr=text=>window.MotionBuilderI18n?.translate?.(text)||text;
  for(const backend of Object.keys(researchFeatureIds)){
    const allowed=researchFeatureAllowed(backend),view=researchFeaturePresentation(backend),busy=backend==="gvhmr"&&state.motions.some(isProcessingMotion);
    const ids=backend==="hybrik"?["poseImagePickBtn","poseImage","runPoseInferenceBtn"]:["motionVideoButton","motionVideo","motionSubmitBtn","motionStartInferenceBtn"];
    for(const id of ids){const control=$(id);if(!control)continue;const needsFile=id==="runPoseInferenceBtn"?!pendingPoseImageFile:(id==="motionSubmitBtn"||id==="motionStartInferenceBtn")&&!$("motionVideo")?.files?.[0];control.disabled=!allowed||busy||Boolean(needsFile);control.setAttribute("aria-disabled",String(control.disabled));control.dataset.researchState=view.state;control.classList.toggle("research-release-unavailable",!allowed);control.title=tr(busy?"已有视频动作正在生成":view.message)}
    const notice=$(backend==="hybrik"?"poseReleaseNotice":"motionReleaseNotice");
    if(notice){notice.dataset.researchState=view.state;notice.querySelector("strong").textContent=tr(view.badge);notice.querySelector("span").textContent=tr(view.message)}
  }
}
async function loadReleaseCapabilities(){try{const value=await api("/api/capabilities");releaseCapabilities=validReleaseCapabilities(value)?value:null}catch{releaseCapabilities=null}releaseCapabilitiesChecked=true;renderResearchAvailability();renderHealthBadge()}
