function renderHealthBadge(){
  const badge=$("health");
  const tr=text=>window.MotionBuilderI18n?.translate?.(text)||text;
  if(!healthChecked){badge.className="health";badge.textContent=tr("状态：检查中");badge.title=tr("正在检查工作台服务与发布能力。");badge.dataset.serviceReady="false";return}
  const serviceReady=Boolean(healthSnapshot&&(typeof healthSnapshot.service_ready==="boolean"?healthSnapshot.service_ready:healthSnapshot.ok));
  const experimentalUnavailable=serviceReady&&Object.values(releaseCapabilities?.features||{}).some(feature=>feature.state==="disabled_experimental");
  const optionalMissing=serviceReady&&(experimentalUnavailable||healthSnapshot.rigging?.ready===false||Object.values(healthSnapshot.optional_backends||{}).some(backend=>backend?.ready===false));
  badge.className=`health ${serviceReady?(optionalMissing?"optional":"ok"):"bad"}`;
  badge.textContent=tr(!serviceReady?"状态：错误":experimentalUnavailable?"在线 · 实验性功能":optionalMissing?"在线 · 可选后端未配置":"状态：在线");
  badge.title=tr(!serviceReady?"工作台服务无法连接或尚未就绪。":experimentalUnavailable?"工作台在线；公开版暂不启用图片与视频新推理，其它功能按各自资源与依赖条件使用。":optionalMissing?"工作台在线；部分可选后端尚未配置，已有资产编辑仍可使用。":"工作台服务在线；后端文件状态不代表模型运行或许可验证。");
  badge.dataset.serviceReady=String(serviceReady);
}
