  box.querySelectorAll("[data-kimodo-prompt]").forEach(input=>input.oninput=()=>{state.kimodoSegments[+input.dataset.kimodoPrompt].prompt=input.value});
  box.querySelectorAll("[data-kimodo-duration]").forEach(input=>input.oninput=()=>{state.kimodoSegments[+input.dataset.kimodoDuration].duration_sec=+input.value||1;syncKimodoPredictedTimeline()});
  box.querySelectorAll("[data-kimodo-remove]").forEach(btn=>btn.onclick=()=>{state.kimodoSegments.splice(+btn.dataset.kimodoRemove,1);renderKimodoSegments();syncKimodoPredictedTimeline()});
