function matrix(rows,index){return new THREE.Matrix4().set(...rows[index])}
function disposePlayer(t){if(!t)return;t.gizmo?.detach();if(t.mesh){t.scene.remove(t.mesh);t.mesh.geometry.dispose();t.mesh.material.dispose()}if(t.bones?.[0])t.scene.remove(t.bones[0]);if(t.helper)t.scene.remove(t.helper);for(const marker of t.markers||[]){t.scene.remove(marker);marker.geometry.dispose();marker.material.dispose()}clearRootCurveObjects(t);if(t.rootMarker){t.scene.remove(t.rootMarker);t.rootMarker.geometry.dispose();t.rootMarker.material.dispose();t.rootMarker=null}for(const arrow of Object.values(t.rootArrows||{})){t.scene.remove(arrow);arrow.traverse?.(o=>{o.geometry?.dispose?.();o.material?.dispose?.()})}t.rootArrows={};t.markers=[];t.selectedJoint=-1}
function makeBones(sceneData){const bones=sceneData.names.map(n=>{const b=new THREE.Bone();b.name=n;return b}),world=sceneData.target_bind.map((_,i)=>matrix(sceneData.target_bind,i));bones.forEach((b,i)=>{const p=sceneData.parents[i],local=p<0?world[i].clone():world[p].clone().invert().multiply(world[i]);local.decompose(b.position,b.quaternion,b.scale);if(p>=0)bones[p].add(b)});return {bones,world}}
const WORKBENCH_SCENE_BACKGROUND=0x0f1115,WORKBENCH_GRID_MAJOR=0x333333,WORKBENCH_GRID_MINOR=0x222222;
function makeWorkbenchGrid(){return new THREE.GridHelper(4,20,WORKBENCH_GRID_MAJOR,WORKBENCH_GRID_MINOR)}
function initSimplePlayer(canvasId,timelineId,labelId,playId){const canvas=$(canvasId),renderer=new THREE.WebGLRenderer({canvas,antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));const scene=new THREE.Scene();scene.background=new THREE.Color(WORKBENCH_SCENE_BACKGROUND);const camera=new THREE.PerspectiveCamera(42,1,.01,100);camera.position.set(2,1.3,3);const controls=new OrbitControls(camera,canvas);controls.target.set(0,.9,0);scene.add(new THREE.HemisphereLight(0xdbe8ff,0x172238,2.5));const key=new THREE.DirectionalLight(0xffffff,3);key.position.set(2,4,3);scene.add(key,makeWorkbenchGrid());const player={canvas,renderer,scene,camera,controls,timelineId,labelId,playId,mesh:null,bones:[],helper:null,rootObjects:[],rootMarker:null,sceneData:null,frames:[],frame:0,playing:false,lastTick:0};$(playId).onclick=()=>{player.playing=!player.playing;player.lastTick=0;$(playId).textContent=player.playing?"⏸":"▶"};$(timelineId).oninput=e=>setSimpleFrame(player,+e.target.value);renderer.setAnimationLoop(t=>{if(player.playing&&player.sceneData){const step=1000/player.sceneData.fps;if(!player.lastTick)player.lastTick=t;if(t-player.lastTick>=step){setSimpleFrame(player,(player.frame+1)%player.sceneData.num_frames);player.lastTick=t}}controls.update();renderer.render(scene,camera)});return player}
function resizeSimple(player){if(!player)return;const rect=player.canvas.getBoundingClientRect();player.renderer.setSize(Math.max(1,rect.width),Math.max(1,rect.height),false);player.camera.aspect=rect.width/Math.max(1,rect.height);player.camera.updateProjectionMatrix()}
function clearSimplePlayer(player){if(player.mesh){player.scene.remove(player.mesh);player.mesh.geometry.dispose();player.mesh.material.dispose()}else if(player.bones?.[0])player.scene.remove(player.bones[0]);if(player.helper)player.scene.remove(player.helper);for(const object of player.rootObjects||[]){player.scene.remove(object);object.geometry?.dispose?.();object.material?.dispose?.()}player.mesh=null;player.bones=[];player.helper=null;player.rootObjects=[];player.rootMarker=null}
function fitStaticMeshPreview(player,mesh){mesh.geometry.computeBoundingBox();const box=mesh.geometry.boundingBox;if(!box||box.isEmpty())return;const center=new THREE.Vector3(),size=new THREE.Vector3();box.getCenter(center);box.getSize(size);const radius=Math.max(size.x,size.y,size.z,.35);player.controls.target.copy(center);player.camera.near=Math.max(.001,radius/200);player.camera.far=Math.max(100,radius*20);player.camera.position.copy(center).add(new THREE.Vector3(radius*1.15,radius*.72,radius*2.05));player.camera.updateProjectionMatrix();player.controls.update()}
function buildSimpleCharacter(player,s,options={}){
  clearSimplePlayer(player);
  s.target_bind=s.target_bind||s.bind_matrices;
  s.fps=s.fps||30;
  s.num_frames=s.num_frames||1;
  const hasSkeleton=!!(s.target_bind?.length&&s.parents?.length&&s.names?.length);
  const hasMesh=!!(s.vertices?.length&&s.faces?.length);
  const hasSkin=!!(hasMesh&&s.lbs_indices?.length&&s.lbs_weights?.length);
  if(s.static_asset||!hasSkeleton){
    const geo=new THREE.BufferGeometry();
    geo.setAttribute("position",new THREE.Float32BufferAttribute((s.vertices||[]).flat(),3));
    geo.setIndex((s.faces||[]).flat());
    geo.computeVertexNormals();
    const material=options.wireframe?new THREE.MeshBasicMaterial({color:0xffffff,wireframe:true,wireframeLinewidth:.45,transparent:true,opacity:.46,side:THREE.DoubleSide}):new THREE.MeshStandardMaterial({color:0xff858c,roughness:.68,side:THREE.DoubleSide});
    const mesh=new THREE.Mesh(geo,material);
    player.scene.add(mesh);
    Object.assign(player,{mesh,bones:[],helper:null});
    fitStaticMeshPreview(player,mesh);
    resizeSimple(player);
    return;
  }
  const built=makeBones(s);
  if(!hasSkin){
    player.scene.add(built.bones[0]);
    let helper=null;
    if(!options.hideSkeleton){
      helper=new THREE.SkeletonHelper(built.bones[0]);
      helper.material.linewidth=2;
      player.scene.add(helper);
    }
    Object.assign(player,{mesh:null,bones:built.bones,helper});
    resizeSimple(player);
    return;
  }
  const geo=new THREE.BufferGeometry();
  geo.setAttribute("position",new THREE.Float32BufferAttribute(s.vertices.flat(),3));
  geo.setIndex(s.faces.flat());
  geo.computeVertexNormals();
  geo.setAttribute("skinIndex",new THREE.Uint16BufferAttribute(s.lbs_indices.flat(),4));
  geo.setAttribute("skinWeight",new THREE.Float32BufferAttribute(s.lbs_weights.flat(),4));
  const material=options.wireframe?new THREE.MeshBasicMaterial({color:0xffffff,wireframe:true,wireframeLinewidth:.45,transparent:true,opacity:.46,side:THREE.DoubleSide}):new THREE.MeshStandardMaterial({color:0x83aef7,roughness:.62,side:THREE.DoubleSide});
  const skeleton=new THREE.Skeleton(built.bones,built.world.map(m=>m.clone().invert())),mesh=new THREE.SkinnedMesh(geo,material);
  mesh.add(built.bones[0]);
  mesh.bind(skeleton,new THREE.Matrix4());
  player.scene.add(mesh);
  let helper=null;
  if(!options.hideSkeleton){
    helper=new THREE.SkeletonHelper(mesh);
    player.scene.add(helper);
  }
  Object.assign(player,{mesh,bones:built.bones,helper});
  if(s.virtual_root_path?.length&&!options.hideRootPath){
    const path=new THREE.BufferGeometry().setFromPoints(s.virtual_root_path.map(p=>new THREE.Vector3(p[0],p[1],p[2]))),line=new THREE.Line(path,new THREE.LineBasicMaterial({color:0x42f5d7})),marker=new THREE.Mesh(new THREE.SphereGeometry(.045,18,12),new THREE.MeshBasicMaterial({color:0x42f5d7,depthTest:false}));
    marker.renderOrder=5;
    player.scene.add(line);
    player.scene.add(marker);
    player.rootObjects=[line,marker];
    player.rootMarker=marker;
  }
  resizeSimple(player);
}
function setSimpleFrame(player,frame){if(!player.sceneData||!player.frames[frame])return;player.frame=Math.max(0,Math.min(frame,player.sceneData.num_frames-1));const world=player.frames[player.frame].map(a=>new THREE.Matrix4().set(...a));player.bones.forEach((b,i)=>{const p=player.sceneData.parents[i],local=p<0?world[i]:world[p].clone().invert().multiply(world[i]);local.decompose(b.position,b.quaternion,b.scale)});if(player.adjustEdits)applyAnimationAdjustEdits(player);player.mesh?.skeleton?.update();if(player.ikEnabled&&!studioIKController(player)?.transformControls?.dragging)syncStudioIKFromPose(player);if(player.rootMarker&&player.sceneData.virtual_root_path?.[player.frame]){const p=player.sceneData.virtual_root_path[player.frame];player.rootMarker.position.set(p[0],p[1],p[2])}if(player.adjustMarkers)updateAnimationAdjustMarkers(player);if(player.adjustEdits&&!player.gizmo?.dragging)refreshAnimationAdjustSelectedBase(player);$(player.timelineId).value=player.frame;$(player.labelId).textContent=`${player.frame+1} / ${player.sceneData.num_frames}`;player.onFrameChange?.(player.frame,player.sceneData.num_frames)}
function matrixRowArray(m){const e=m.elements;return[e[0],e[4],e[8],e[12],e[1],e[5],e[9],e[13],e[2],e[6],e[10],e[14],e[3],e[7],e[11],e[15]]}
function applyVirtualRootToFrames(sceneData,frames){if(!sceneData.virtual_root_transforms?.length)return frames;return frames.map((frame,i)=>{const root=sceneData.virtual_root_transforms[i];if(!root)return frame;const rootMatrix=new THREE.Matrix4().set(...root);return frame.map(joint=>matrixRowArray(rootMatrix.clone().multiply(new THREE.Matrix4().set(...joint))))})}
async function loadSimpleResource(player,prefix,id,options={}){player.sceneData=await api(`${prefix}/${id}/scene`);player.sceneData.target_bind=player.sceneData.target_bind||player.sceneData.bind_matrices;player.sceneData.fps=player.sceneData.fps||30;player.sceneData.num_frames=player.sceneData.num_frames||1;player.frames=[];buildSimpleCharacter(player,player.sceneData);window.TerrainWorkspace?.syncPlayerTerrain?.(player,player.sceneData.terrain||null);if(player.sceneData.static_asset){player.frames=[[]];player.sceneData.num_frames=1}else if(options.staticPose||prefix==="/api/characters"){player.frames=[player.sceneData.target_bind];player.sceneData.num_frames=1}else{for(let i=0;i<player.sceneData.num_frames;i+=240){const part=await api(`${prefix}/${id}/frames?from_frame=${i}&to_frame=${Math.min(player.sceneData.num_frames,i+240)}`);player.frames.push(...part.world)}if(options.applyVirtualRoot)player.frames=applyVirtualRootToFrames(player.sceneData,player.frames)}$(player.timelineId).max=player.sceneData.num_frames-1;$(player.playId).disabled=player.sceneData.num_frames<=1;setSimpleFrame(player,0);if(!player.sceneData.static_asset)fitSkeletonPreview(player,player.frames);resizeSimple(player)}
