  const camera=new THREE.PerspectiveCamera(42,1,.01,100);camera.position.set(2,1.3,3);
  const controls=new OrbitControls(camera,canvas);controls.target.set(0,.9,0);
  scene.add(new THREE.HemisphereLight(0xdbe8ff,0x172238,2.5));
  const key=new THREE.DirectionalLight(0xffffff,3);key.position.set(2,4,3);scene.add(key,makeWorkbenchGrid());
  const gizmo=new TransformControls(camera,canvas);scene.add(gizmo.getHelper());
  const player={canvas,renderer,scene,camera,controls,gizmo,mesh:null,bones:[],helper:null,markers:[],rootArrows:{},rootMarker:null,rootCurveObjects:[],rootCurveLine:null,rootCurveMarkers:[],raycaster:new THREE.Raycaster(),pointer:new THREE.Vector2(),selectedJoint:-1,basePosition:null,baseQuaternion:null,updatingPose:false};
