  gizmo.addEventListener("objectChange",()=>state.attachments.mode?syncAttachmentGizmo():state.rootCurve.mode?syncCurveGizmo():state.segmentCurve.mode?syncSegmentCurveGizmo():syncGizmoInputs());
  canvas.addEventListener("pointerdown",event=>state.attachments.mode?selectAttachmentModePointer(event):state.rootCurve.mode?selectCurvePointFromPointer(event):state.segmentCurve.mode?selectSegmentCurveFromPointer(event):activeEditorToolMode==="bone"?selectBoneFromPointer(event):null);
  renderer.setAnimationLoop(t=>{if(state.playing&&state.scene){const step=1000/state.scene.fps;if(!state.lastTick)state.lastTick=t;if(t-state.lastTick>=step){setFrame((state.frame+1)%state.scene.num_frames);state.lastTick=t}}controls.update();renderer.render(scene,camera)});
