const FINAL_TIMELINE_HEIGHT_KEY="motionbuilder-final-timeline-height";
function finalTimelineHeightBounds(){const stage=document.querySelector("#tab-edit .final-preview-stage"),height=Math.max(320,stage?.clientHeight||0);return{min:148,max:Math.max(148,Math.floor(height*.72))}}
