function selectBoneFromPointer(event){const t=state.three;if(t?.ikEnabled||!t?.markers?.length||t.gizmo.dragging)return;const rect=$("sceneCanvas").getBoundingClientRect();t.pointer.set((event.clientX-rect.left)/rect.width*2-1,-((event.clientY-rect.top)/rect.height)*2+1);t.raycaster.setFromCamera(t.pointer,t.camera);const hit=t.raycaster.intersectObjects(t.markers,false)[0];if(hit)selectBone(hit.object.userData.joint)}
function baseLocalTransform(index){const world=state.frames[state.frame].map(a=>new THREE.Matrix4().set(...a)),p=state.scene.parents[index],local=p<0?world[index]:world[p].clone().invert().multiply(world[index]),position=new THREE.Vector3(),quaternion=new THREE.Quaternion(),scale=new THREE.Vector3();local.decompose(position,quaternion,scale);return {position,quaternion}}
function storeCurrentInputs(){const t=state.three,index=t?.selectedJoint;if(t?.ikEnabled)return;if(index===undefined||index<0)return;const translation=[+$("tx").value,+$("ty").value,+$("tz").value],euler=new THREE.Euler(THREE.MathUtils.degToRad(+$('rx').value),THREE.MathUtils.degToRad(+$('ry').value),THREE.MathUtils.degToRad(+$('rz').value),'XYZ'),q=new THREE.Quaternion().setFromEuler(euler),changed=translation.some(v=>Math.abs(v)>1e-7)||Math.abs(q.x)+Math.abs(q.y)+Math.abs(q.z)>1e-7;if(changed)state.pendingBoneEdits.set(index,{translation,rotation:[q.x,q.y,q.z,q.w]})}
function applyPendingBoneEdits(){const t=state.three;if(!t?.mesh)return;t.updatingPose=true;for(const [index,edit] of state.pendingBoneEdits){const bone=t.bones[index];if(!bone)continue;bone.position.add(new THREE.Vector3(...edit.translation));bone.quaternion.multiply(new THREE.Quaternion(...edit.rotation))}t.mesh.skeleton.update();updateBoneMarkers();t.updatingPose=false}
function selectBone(index){if(activeEditorToolMode!=="bone")return;const t=state.three;if(!t?.bones[index])return;storeCurrentInputs();state.playing=false;$("playBtn").textContent="▶";t.selectedJoint=index;$("jointSelect").value=String(index);applyFrame(state.frame);applyPendingBoneEdits();t.markers.forEach((m,i)=>m.material.color.setHex(i===index?0x49e6ff:0xffcb58));if(!t.ikEnabled){t.gizmo.attach(t.bones[index]);setSelectedBoneBaseAndInputs()}}
function setSelectedBoneBaseAndInputs(){const t=state.three,index=t?.selectedJoint,bone=t?.bones[index];if(!bone)return;const base=baseLocalTransform(index);t.basePosition=base.position;t.baseQuaternion=base.quaternion;const edit=state.pendingBoneEdits.get(index);if(edit){const euler=new THREE.Euler().setFromQuaternion(new THREE.Quaternion(...edit.rotation),"XYZ");[$("tx").value,$("ty").value,$("tz").value]=edit.translation.map(v=>v.toFixed(4));$("rx").value=THREE.MathUtils.radToDeg(euler.x).toFixed(2);$("ry").value=THREE.MathUtils.radToDeg(euler.y).toFixed(2);$("rz").value=THREE.MathUtils.radToDeg(euler.z).toFixed(2)}else{for(const id of ["tx","ty","tz","rx","ry","rz"])$(id).value=0}}
function syncGizmoInputs(){if(activeEditorToolMode!=="bone"||state.three?.ikEnabled)return;const t=state.three,bone=t?.bones[t.selectedJoint];if(!bone||!t.basePosition||!t.baseQuaternion||t.updatingPose)return;const delta=bone.position.clone().sub(t.basePosition),q=t.baseQuaternion.clone().invert().multiply(bone.quaternion),euler=new THREE.Euler().setFromQuaternion(q,"XYZ"),edit={translation:[delta.x,delta.y,delta.z],rotation:[q.x,q.y,q.z,q.w]};state.pendingBoneEdits.set(t.selectedJoint,edit);$("tx").value=delta.x.toFixed(4);$("ty").value=delta.y.toFixed(4);$("tz").value=delta.z.toFixed(4);$("rx").value=THREE.MathUtils.radToDeg(euler.x).toFixed(2);$("ry").value=THREE.MathUtils.radToDeg(euler.y).toFixed(2);$("rz").value=THREE.MathUtils.radToDeg(euler.z).toFixed(2);$("editorStatus").textContent=`待提交骨骼调整：${state.pendingBoneEdits.size}`;updateBoneMarkers()}
function staticAttachmentAssets(){return state.characters.filter(isStaticCharacter)}
function refreshAttachmentAssetOptions(){const sel=$("attachmentAssetSelect");if(!sel)return;const current=sel.value,assets=staticAttachmentAssets();sel.innerHTML=assets.length?assets.map(c=>`<option value="${c.id}">${escapeHtml(c.name)}</option>`).join(""):`<option value="">无静态网格体</option>`;if(assets.some(c=>c.id===current))sel.value=current}
function attachmentConfig(item){return {asset_id:item.asset_id,name:item.name,joint:item.joint,position:item.mesh.position.toArray(),quaternion:item.mesh.quaternion.toArray(),scale:item.mesh.scale.x}}
