function disposeAttachmentMesh(mesh){if(!mesh)return;mesh.removeFromParent();mesh.traverse?.(o=>{o.geometry?.dispose?.();if(Array.isArray(o.material))o.material.forEach(m=>m.dispose?.());else o.material?.dispose?.()})}
