async function ensureAttachmentAsset(id){if(!id)throw new Error("请选择一个静态网格体");if(state.attachments.assetCache[id])return state.attachments.assetCache[id];if(!state.attachments.assetPromises[id])state.attachments.assetPromises[id]=api(`/api/characters/${id}/scene`);const data=await state.attachments.assetPromises[id];state.attachments.assetCache[id]=data;return data}
function makeAttachmentMesh(sceneData,name){const geo=new THREE.BufferGeometry();geo.setAttribute("position",new THREE.Float32BufferAttribute((sceneData.vertices||[]).flat(),3));geo.setIndex((sceneData.faces||[]).flat());geo.computeVertexNormals();const mat=new THREE.MeshStandardMaterial({color:0xff6b6b,roughness:.62,metalness:.08,side:THREE.DoubleSide,transparent:true,opacity:.94});const mesh=new THREE.Mesh(geo,mat);mesh.name=name||"Attachment";mesh.castShadow=false;mesh.receiveShadow=false;return mesh}
async function addAttachmentFromConfig(config){const t=state.three;if(!t?.bones?.[config.joint])throw new Error("当前骨骼网格体不可用");const asset=await ensureAttachmentAsset(config.asset_id),mesh=makeAttachmentMesh(asset,config.name);mesh.userData.attachmentId=config.id||crypto.randomUUID?.()||String(Date.now()+Math.random());mesh.position.fromArray(config.position||[0,0,0]);mesh.quaternion.fromArray(config.quaternion||[0,0,0,1]);mesh.scale.setScalar(config.scale||.2);t.bones[config.joint].add(mesh);const item={id:mesh.userData.attachmentId,asset_id:config.asset_id,name:config.name||state.characters.find(c=>c.id===config.asset_id)?.name||"附着物",joint:config.joint,mesh};state.attachments.items.push(item);return item}
