function selectAttachmentJoint(index){const t=state.three;if(!t?.bones[index])return;state.attachments.selectedJoint=index;t.markers.forEach((m,i)=>m.material.color.setHex(i===index?0xff4d4d:0xffcb58));$("editorStatus").textContent=`已选择骨骼：${state.scene.names[index]}。选择静态网格体后点击“添加组件到选中骨骼”。`;renderAttachmentPanel()}
function selectAttachmentItem(id){const item=state.attachments.items.find(x=>x.id===id);if(!item)return;state.attachments.selectedId=id;state.attachments.selectedJoint=item.joint;state.three?.markers?.forEach((m,i)=>m.material.color.setHex(i===item.joint?0xff4d4d:0xffcb58));$("editorStatus").textContent=`正在调整：${item.name} → ${state.scene.names[item.joint]}`;state.three?.gizmo.attach(item.mesh);renderAttachmentPanel()}
function selectAttachmentModePointer(event){const t=state.three;if(!t||t.gizmo.dragging)return;const rect=$("sceneCanvas").getBoundingClientRect();t.pointer.set((event.clientX-rect.left)/rect.width*2-1,-((event.clientY-rect.top)/rect.height)*2+1);t.raycaster.setFromCamera(t.pointer,t.camera);const meshes=state.attachments.items.map(i=>i.mesh);const attachmentHit=t.raycaster.intersectObjects(meshes,true)[0];if(attachmentHit){let obj=attachmentHit.object;while(obj&&!obj.userData.attachmentId)obj=obj.parent;if(obj?.userData.attachmentId)selectAttachmentItem(obj.userData.attachmentId);return}const boneHit=t.raycaster.intersectObjects(t.markers||[],false)[0];if(boneHit)selectAttachmentJoint(boneHit.object.userData.joint)}
async function attachSelectedAssetToBone(){if(!state.attachments.mode)return;const joint=state.attachments.selectedJoint;if(joint<0){$("editorStatus").textContent="请先在预览视口中选择一个骨骼节点。";return}try{const assetId=$("attachmentAssetSelect").value,item=await addAttachmentFromConfig({asset_id:assetId,joint,scale:.2});selectAttachmentItem(item.id);$("editorStatus").textContent=`已附着：${item.name} → ${state.scene.names[joint]}。可用 Gizmo 调整位置/旋转/整体缩放。`}catch(e){$("editorStatus").textContent=e.message}}
function deleteAttachment(id){const item=state.attachments.items.find(x=>x.id===id);if(!item)return;disposeAttachmentMesh(item.mesh);state.attachments.items=state.attachments.items.filter(x=>x.id!==id);if(state.attachments.selectedId===id){state.attachments.selectedId=null;state.three?.gizmo.detach()}renderAttachmentPanel()}
function syncAttachmentGizmo(force=false){if(!state.attachments.mode)return;const item=state.attachments.items.find(x=>x.id===state.attachments.selectedId);if(item&&state.attachments.gizmoMode==="scale"){const s=Math.max(.001,(item.mesh.scale.x+item.mesh.scale.y+item.mesh.scale.z)/3);item.mesh.scale.setScalar(s)}if(force)renderAttachmentPanel()}
function setAttachmentGizmoMode(mode){const t=state.three;if(!t)return;state.attachments.gizmoMode=mode;t.gizmo.setMode(mode);t.gizmo.setSpace("local");$("attachmentTranslate")?.classList.toggle("active",mode==="translate");$("attachmentRotate")?.classList.toggle("active",mode==="rotate");$("attachmentScale")?.classList.toggle("active",mode==="scale")}
function renderAttachmentPanel(){refreshAttachmentAssetOptions();const box=$("attachmentList");if(!box)return;box.innerHTML=state.attachments.items.length?state.attachments.items.map(item=>`<div class="attachment-row ${item.id===state.attachments.selectedId?"selected":""}" data-attachment-row="${item.id}"><span>${escapeHtml(item.name)} → ${escapeHtml(state.scene?.names?.[item.joint]||String(item.joint))}</span><small>位置 ${item.mesh.position.toArray().map(v=>v.toFixed(2)).join(", ")} · 缩放 ${item.mesh.scale.x.toFixed(2)}</small><div class="actions"><button data-select-attachment="${item.id}">选择</button><button data-delete-attachment="${item.id}">删除</button></div></div>`).join(""):"";box.querySelectorAll("[data-select-attachment]").forEach(b=>b.onclick=e=>{e.stopPropagation();selectAttachmentItem(b.dataset.selectAttachment)});box.querySelectorAll("[data-delete-attachment]").forEach(b=>b.onclick=e=>{e.stopPropagation();deleteAttachment(b.dataset.deleteAttachment)});box.querySelectorAll("[data-attachment-row]").forEach(row=>row.onclick=()=>selectAttachmentItem(row.dataset.attachmentRow))}
function enterAttachmentMode(){if(!state.scene||!state.three?.bones?.length){alert("请先在时间轴内添加至少一段动画，并载入骨骼网格体。");return}if(state.rootCurve.mode||state.segmentCurve.mode||state.orientation.mode){alert("请先退出当前曲线/朝向模式。");return}state.playing=false;$("playBtn").textContent="▶";state.pendingBoneEdits.clear();state.three.selectedJoint=-1;state.attachments.mode=true;state.attachments.snapshot=attachmentSnapshot();state.attachments.selectedJoint=-1;state.attachments.selectedId=null;setBoneControlsHidden(true);setTimelineMutationDisabled(true);showEditorToolMode("component");state.three.gizmo.detach();setAttachmentGizmoMode("translate");renderAttachmentPanel();$("editorStatus").textContent="点击预览视口中的骨骼节点，然后选择静态网格体并附着。"}
