function finalSceneIKFamily(solver){return solver==="two_bone"?"two_bone":"full_body"}
async function configureFinalSceneIKMode(solver,enabled=true){
  const t=state.three;
  if(!t?.mesh)return;
  if(enabled)await ensureFinalIKControllers();
  const family=finalSceneIKFamily(solver);
  for(const view of t.ikControllers?.twoBone?.chainViews?.values?.()||[]){view.pole.visible=!(enabled&&family==="two_bone");view.poleGuide.visible=!(enabled&&family==="two_bone")}
  setStudioIKEnabled(t,Boolean(enabled),family);
  t.gizmo?.detach();
  if(t.gizmo?.getHelper())t.gizmo.getHelper().visible=!enabled;
  t.markers?.forEach(marker=>marker.visible=!enabled);
  if(!enabled)return;
  syncStudioIKFromPose(t);
  const controller=studioIKController(t);
  controller?.setTransformMode($("ikLockRotateBtn")?.classList.contains("active")?"rotate":"translate");
  controller?.setTransformSpace("world");
  if(family==="two_bone"&&controller?.selected?.userData?.ikControlType==="pole")controller.selectControl(controller.controls.find(control=>control.userData?.ikControlType==="goal"));
  else if(controller?.selected)controller.selectControl(controller.selected);
  else if(controller?.controls?.length)controller.selectControl(controller.controls[0]);
}
function setFinalSceneIKTransformMode(mode){studioIKController(state.three)?.setTransformMode(mode)}
function setFinalSceneIKControllerGizmoVisible(visible){
  const controller=studioIKController(state.three),helper=controller?.transformControls?.getHelper?.();
  if(!controller?.transformControls)return;
  if(visible&&controller.enabled&&controller.selected)controller.transformControls.attach(controller.selected);
  else controller.transformControls.detach();
  if(helper)helper.visible=Boolean(visible&&controller.enabled);
}
function selectFinalSceneIKEffector(solver,jointName){
  const controllers=state.three?.ikControllers;
  if(!controllers)return false;
  const family=finalSceneIKFamily(solver),controller=family==="two_bone"?controllers.twoBone:controllers.fullBody;
  const view=family==="two_bone"
    ?[...controller.chainViews.values()].find(item=>item.chain?.joint_names?.[2]===jointName)
    :[...controller.views.values()].find(item=>item.effector?.bone===jointName);
  const control=family==="two_bone"?view?.goal:view?.control;
  if(!control)return false;
  controller.selectControl(control);
  return true;
}
async function previewFinalSceneIK(constraint,marker){
  const t=state.three;
  if(!t?.mesh||!marker)return;
  const controllers=await ensureFinalIKControllers();
  const fullBody=constraint.solver!=="two_bone";
  if(activeEditorToolMode==="iklock"&&(!t.ikEnabled||t.ikControllers?.solver!==(fullBody?"full_body":"two_bone")))await configureFinalSceneIKMode(constraint.solver,true);
  if(fullBody){
    const controller=controllers.fullBody;
    controller.syncControlsFromPose({capture:true});
    const view=[...controller.views.values()].find(item=>item.effector?.bone===constraint.joint_name);
    if(!view)return;
    view.control.position.copy(marker.position);
    view.control.quaternion.copy(marker.quaternion);
    controller.setRootBehavior(constraint.root_behavior==="pin"?"pin_to_input":constraint.root_behavior==="free"?"free":"pre_pull");
    controller.setIterations(constraint.iterations||24);
    controller.solve();
  }else{
    const controller=controllers.twoBone;
    controller.syncControlsFromPose();
    const view=[...controller.chainViews.values()].find(item=>item.chain?.joint_names?.[2]===constraint.joint_name);
    if(!view)return;
    view.goal.position.copy(marker.position);
    view.goal.quaternion.copy(marker.quaternion);
    controller.solveChain(view.chain.id);
  }
  t.mesh.skeleton.update();
  updateBoneMarkers();
}
