const finalSceneBaseRenderTimelineTrack=renderTimelineTrack;
renderTimelineTrack=function(){
  finalSceneBaseRenderTimelineTrack();
  const track=$("timelineTrack");
  if(!track||!finalSceneTools)return;
  const tops=[...track.querySelectorAll(".edit-marker")].map(node=>parseFloat(node.style.top)||0);
  const top=Math.max(114,...tops.map(value=>value+42));
  const lanes=finalSceneTools.appendTimelineTracks(track,Math.max(1,state.scene?.num_frames||1),top);
  if(lanes)track.style.height=Math.max(parseFloat(track.style.height)||0,top+lanes*42+12)+"px";
};
async function initFinalSceneTools(){
  try{
    const {createFinalSceneTools}=await import("/app-static/final_scene_tools.js?v=6");
    finalSceneTools=createFinalSceneTools({
      state,
      api,
      escapeHtml,
      getThree:()=>THREE,
      getTransformControls:()=>TransformControls,
      getRuntime:()=>state.three,
      getStaticAssets:()=>state.characters.filter(isStaticCharacter),
      showMode:showEditorToolMode,
      setStatus:value=>{if($("editorStatus"))$("editorStatus").textContent=value},
      setTimelineMutationDisabled,
      setFrame:value=>setFrame(value),
      renderTimeline:()=>renderTimelineTrack(),
      previewIK:previewFinalSceneIK,
      configureIKMode:configureFinalSceneIKMode,
      setIKTransformMode:setFinalSceneIKTransformMode,
      setIKControllerGizmoVisible:setFinalSceneIKControllerGizmoVisible,
      selectIKEffector:selectFinalSceneIKEffector,
      resetPose:()=>{if(state.scene){applyFrame(state.frame);applyPendingBoneEdits();updateBoneMarkers()}},
      onCompositionChange:row=>{
        state.composition={...(state.composition||{}),...row};
        if(state.scene){
          state.scene.scene_objects=row.scene_objects||state.scene.scene_objects||[];
          state.scene.ik_constraints=row.ik_constraints||state.scene.ik_constraints||[];
        }
      },
      reloadComposition:async preserve=>{if(state.composition)await loadResource("/api/compositions",state.composition.id,Boolean(preserve))},
    });
    finalSceneTools.attachRuntime();
    updateRootCurveUi();
  }catch(error){
    console.error("Final scene tools failed to initialize",error);
    if($("editorStatus")&&!$("editorStatus").textContent)$("editorStatus").textContent="Scene / IK tools failed to initialize: "+error.message;
  }
}
