        onWaypointPoseChange:pose=>{const point=state.kimodoTrajectory.points[state.kimodoTrajectory.selected];if(point)point.pose_override=pose?JSON.parse(JSON.stringify(pose)):null},
        onWaypointTransformChange:()=>{renderKimodoTrajectory();renderKimodoConstraintPreview()},
